from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent
records=[]
for reader in 'ab':
 p=f'''Independent blind summary reader. Read ONLY {R}/full-iteration-05/summary-snapshot.md and questions.json in that same directory. No other files, sources, key, manifests, prior outputs, parent history, links, browsing, prior game knowledge or communicating with others. Read the COMPLETE inputs in chunks if output truncates. Answer ALL108 questions from summary. For EACH question, first enumerate its requested clauses in a requested_parts array, then give an answer string with separate numbered rulings for every one of those clauses. Include requested quantities, destinations, visibility, timing, exceptions and reasons; do not replace an asked procedure with just its name. Before saving, compare every requested clause with that question's answer and fill omitted facts the summary supports. A citation does not substitute for an answer. No brevity requirement; use multiple tool writes if needed to keep full details. If summary lacks or expressly leaves a fact unresolved, say so; never guess. Each object: id, requested_parts, answer, support(supported/partial/unsupported), evidence(short quote/section). Save valid JSON {{reader,inputs_read,answers:[...]}} to {R}/full-iteration-05/reader-{reader}.json. Read only the two inputs; write only this assigned output. Do not evaluate or improve summary.'''
 records.append({'reader':reader,'prompt':p,'sha256':hashlib.sha256(p.encode()).hexdigest(),'requested_model':'gpt-6-luna','requested_effort':'high','fork_turns':'none','version':'full5-requested-parts-checklist'})
(R/'full-iteration-05/reader-prompts.json').write_text(json.dumps({'recording_basis':'Plaintext dispatch instructions retained from parent tool-call requests. Runtime metadata separately confirms actual models/effort; dispatch messages in local rollout storage are encrypted.','records':records,'comparison_limitation':'The generic completeness reminders evolved across iterations, and full05 adds a requested_parts self-check. No rules, expected answers, grades or question-specific hints were disclosed; source/question/key versions remain explicitly frozen. Results are fixed-bank regression evidence, not a controlled pure-model comparison.','reader_a_continuation':'reader-a-protocol-continuation.json documents premature Q59 stop, preserved raw partial and completion of the same still-blind unchanged assignment.'},indent=2)+'\n')
variants=[{'iterations':['seed-iteration-01','seed-iteration-02','seed-iteration-03'],'protocol':'Guide blind-reader template: only frozen summary/questions; answer all requested parts, abstain unsupported, id/answer/support/evidence; no sources/key/prior outputs/history/web/other knowledge.'},{'iterations':['seed-iteration-04'],'addition':'Use enough detail to resolve every requested part; section citations do not substitute for answering.'},{'iterations':['seed-iteration-05','seed-iteration-06','seed-iteration-08'],'addition':'Enumerate compound requested clauses as separate numbered parts; fully describe requested procedures; check every requested part in same answer.'},{'iterations':['full-iteration-02'],'addition':'Generic clause completeness and procedural detail self-check.'},{'iterations':['full-iteration-04'],'addition':'Explicit complete-input chunking when tool truncates; no telegraphic omissions, no brevity requirement, quantities/destinations/timing/exceptions.'},{'iterations':['full-iteration-05'],'exact_prompts':'full-iteration-05/reader-prompts.json','addition':'requested_parts array plus numbered complete answer and per-question pre-submit check.'}]
(R/'reader-protocol-history.json').write_text(json.dumps({'guide':'docs/quality/summary-qa/README.md reader template','isolation':'fork_turns none for every original reader dispatch; instruction-based file access restriction, not OS filesystem sandbox isolation','model_effort':'All readers explicitly gpt-6-luna/high; all source/coverage/grading reviewers gpt-6.1-sol/high; actual runtime metadata separately retained.','variants':variants,'limitations':'Prompt self-check emphasis changed, so score differences cannot be attributed solely to summary changes or model performance. Questions/keys were held fixed within each repair series; source/key corrections are versioned.'},indent=2)+'\n')
